            .orElseThrow(() -> ApiException.notFound("证物未登记剂量账本: " + evidenceKey));
    List<DoseReturnView> returns = doseReturnRepository.findByEvidenceKey(evidenceKey)
            .stream().map(this::toView).toList();
    return toLedgerView(account, returns);
}

